export const EXIT = { ok: 0, fail: 1, usage: 2, interrupted: 130 } as const;

export function buildProgram(): Command {
  const program = new Command();
  program
    .name("harness-tutor")
    .version("0.1.0")
    .option("--no-color", "desativa cor no output")
    .option("--json", "emite saida JSON em stdout", false)
    .showHelpAfterError();

  program.command("init")
    .option("-y, --yes", "nao pergunta nada")
    .option("-d, --dir <path>", "diretorio alvo", ".")
    .option("--dry-run", "mostra o que faria sem escrever")
    .action(runInit);

  program.command("chat")
    .option("-m, --message <text>", "faz uma unica pergunta e sai")
    .option("--offline", "nao chama a rede")
    .action(runChat);

  program.command("test").option("--bail", "para na primeira falha").action(runTest);
  program.command("submit").option("--repo <url>", "URL do repositorio").action(runSubmit);

  return program;
}

