export class CliError extends Error {
  constructor(message: string, readonly exitCode: number = 1, readonly hint?: string) {
    super(message);
    this.name = "CliError";
  }
}

export function toCliError(error: unknown): CliError {
  if (error instanceof CliError) return error;
  if (error instanceof Error) {
    const e = error as Error & { status?: number; code?: string };
    if (e.code === "ENOTFOUND")
      return new CliError("Host da API nao resolvido.", EXIT.fail, "Verifique a conexao e TUTOR_API_URL.");
    if (e.code === "ECONNREFUSED")
      return new CliError("Conexao recusada pela API.", EXIT.fail, "A API esta no ar? Use: pnpm dev");
    if (e.status === 401)
      return new CliError("Credencial invalida.", EXIT.fail, "Rode: harness-tutor init --yes para regerar a chave.");
    if (e.status === 429)
      return new CliError("Limite de taxa atingido.", EXIT.fail, "Aguarde 30s ou reduza TUTOR_MAX_CONCURRENCY.");
    return new CliError(error.message, EXIT.fail);
  }
  return new CliError("Erro desconhecido.", EXIT.fail);
}

const reader = response.body.getReader();
const decoder = new TextDecoder();
let buffer = "";

for (;;) {
  const { done, value } = await reader.read();
  if (done) break;
  buffer += decoder.decode(value, { stream: true });

  let sep = buffer.indexOf("\n\n");
  while (sep !== -1) {
    const raw = buffer.slice(0, sep).trim();
    buffer = buffer.slice(sep + 2);
    sep = buffer.indexOf("\n\n");
    if (!raw.startsWith("data:")) continue;

    const payload = raw.slice(5).trim();
    if (payload === "[DONE]") { yield { type: "done", stopReason: "end_turn" }; return; }

    try {
      const event = JSON.parse(payload) as { type: string; delta?: string; usage?: { input_tokens: number; output_tokens: number } };
      if (event.type === "text" && event.delta) yield { type: "text", delta: event.delta };
      if (event.type === "usage" && event.usage)
        yield { type: "usage", inputTokens: event.usage.input_tokens, outputTokens: event.usage.output_tokens };
    } catch {
      yield { type: "error", message: "Frame SSE invalido recebido." };
      return;
    }
  }
}

const controller = new AbortController();
let interrupted = false;
const onSigint = () => { interrupted = true; controller.abort(); };
process.on("SIGINT", onSigint);

let firstTokenAt: number | undefined;
const consume = async function* (events) {
  for await (const event of events) {
    if (event.type === "text") {
      if (firstTokenAt === undefined) { firstTokenAt = performance.now(); spinner.stop(); }
      stdout.write(event.delta);
    }
    yield event;
  }
};

try {
  for await (const event of consume(streamChat(body, { signal: controller.signal }))) {
    if (event.type === "error") throw new CliError(event.message, EXIT.fail);
  }
} catch (error) {
  const cliError = toCliError(error);
  process.exitCode = interrupted ? EXIT.interrupted : cliError.exitCode;
} finally {
  process.off("SIGINT", onSigint);
}

