export const CheckResultSchema = z.object({
  id: z.string(),
  name: z.string(),
  status: z.enum(["passed", "failed", "skipped"]),
  durationMs: z.number().int().nonnegative(),
  message: z.string(),
});

export const ReportSchema = z.object({
  harnessTutorVersion: z.string(),
  checks: z.array(CheckResultSchema),
  passed: z.number().int().nonnegative(),
  failed: z.number().int().nonnegative(),
  durationMs: z.number().int().nonnegative(),
});

// packages/cli/src/checks/health-check.ts  (adaptador: depende de rede)
export async function runHealthCheck(baseUrl: string, timeoutMs = 3000): Promise<CheckResult> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${baseUrl}/health`, { signal: controller.signal });
    return { id: "api-health", name: `API saudavel em ${baseUrl}`, status: response.ok ? "passed" : "failed", durationMs: 0, message: response.ok ? "OK" : `HTTP ${response.status}` };
  } catch (error) {
    return { id: "api-health", name: `API saudavel em ${baseUrl}`, status: "failed", durationMs: 0, message: error instanceof Error ? error.message : "falha desconhecida" };
  } finally {
    clearTimeout(timer);
  }
}
